//! Generate `seed/benchmark/<slug>.json` from the pinned SWE-bench parquet (S17 step 1).
//!
//! This is a **development tool**, not part of the product: it is excluded from the workspace,
//! its parquet dependency never enters the conveyor's lock or image, and its output is the
//! hashed seed artifact that ships. The eval script is generated by the conveyor's own Rust
//! port of swebench 5.0.2's `make_test_spec` (`crates/domain/src/benchmark/specgen.rs`), which
//! a golden test pins to the harness byte for byte. **No Python runs here.**
//!
//! ```text
//! curl -sL -o /tmp/verified-78f471bf.parquet \
//!   https://huggingface.co/datasets/SWE-bench/SWE-bench_Verified/resolve/\
//! 78f471bf655a3137b2e8a75af1501690ec009ec3/data/test-00000-of-00001.parquet
//!
//! cargo run --manifest-path tools/seed-benchmark/Cargo.toml -- \
//!   --parquet /tmp/verified-78f471bf.parquet \
//!   --images  seed/benchmark/images-verified50-v1.lock.json \
//!   --ids     ~/Movies/conveyor-bench/data/verified50-v1.json \
//!   --out     seed/benchmark/verified50-v1.json
//! ```
//!
//! `seed_sha256` is the SHA-256 of the serialized artifact with the field set to `""`; the
//! seeder recomputes it and refuses a mismatch, so the hash is a property of the bytes.

use std::collections::{BTreeMap, BTreeSet};
use std::error::Error;
use std::fs::{self, File};
use std::path::PathBuf;

use conveyor_domain::benchmark::specgen::{eval_script, oracle_files};
use parquet::file::reader::{FileReader, SerializedFileReader};
use parquet::record::{Field, Row};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

const DATASET: &str = "SWE-bench/SWE-bench_Verified";
const DATASET_REVISION: &str = "78f471bf655a3137b2e8a75af1501690ec009ec3";
const SWEBENCH_VERSION: &str = "5.0.2";
const PARSER_VERSION: &str = "swebench-5.0.2";
const SCHEMA: u32 = 1;

type Result<T> = std::result::Result<T, Box<dyn Error>>;

#[derive(Debug, Deserialize)]
struct ImageLock {
    registry: String,
    images: BTreeMap<String, ImageEntry>,
}

#[derive(Debug, Deserialize)]
struct ImageEntry {
    digest: String,
    repository: String,
}

#[derive(Debug, Serialize)]
struct Seed {
    schema: u32,
    slug: String,
    dataset: &'static str,
    dataset_revision: &'static str,
    swebench_version: &'static str,
    parser_version: &'static str,
    image_lock_sha256: String,
    /// SHA-256 of this document with this field set to `""`.
    seed_sha256: String,
    instances: Vec<InstanceRow>,
}

#[derive(Debug, Serialize)]
struct InstanceRow {
    instance_id: String,
    repo: String,
    version: String,
    base_commit: String,
    image: String,
    problem_statement: String,
    oracle_files: Vec<String>,
    gold_patch: String,
    test_patch: String,
    fail_to_pass: Vec<String>,
    pass_to_pass: Vec<String>,
    eval_script: String,
    parser: String,
}

fn main() {
    if let Err(err) = run() {
        eprintln!("seed-benchmark: {err}");
        std::process::exit(1);
    }
}

fn run() -> Result<()> {
    let mut args = std::env::args().skip(1);
    let mut parquet = None;
    let mut images = None;
    let mut ids_path = None;
    let mut out = None;
    let mut slug = "verified50-v1".to_owned();
    while let Some(flag) = args.next() {
        let value = args.next().ok_or_else(|| format!("{flag} needs a value"))?;
        match flag.as_str() {
            "--parquet" => parquet = Some(PathBuf::from(value)),
            "--images" => images = Some(PathBuf::from(value)),
            "--ids" => ids_path = Some(PathBuf::from(value)),
            "--out" => out = Some(PathBuf::from(value)),
            "--slug" => slug = value,
            other => return Err(format!("unknown argument {other}").into()),
        }
    }
    let (parquet, images, ids_path, out) = (
        parquet.ok_or("--parquet is required")?,
        images.ok_or("--images is required")?,
        ids_path.ok_or("--ids is required")?,
        out.ok_or("--out is required")?,
    );

    let ids: Vec<String> = serde_json::from_str(&fs::read_to_string(&ids_path)?)?;
    if ids.len() != 50 {
        return Err(format!("{} ids, expected 50", ids.len()).into());
    }
    let wanted: BTreeSet<String> = ids.iter().cloned().collect();
    if wanted.len() != ids.len() {
        return Err("the id list contains duplicates".into());
    }

    let lock_bytes = fs::read(&images)?;
    let image_lock_sha256 = hex(&Sha256::digest(&lock_bytes));
    let lock: ImageLock = serde_json::from_slice(&lock_bytes)?;

    let file = File::open(&parquet)?;
    let reader = SerializedFileReader::new(file)?;
    let mut rows: BTreeMap<String, Row> = BTreeMap::new();
    for row in reader.get_row_iter(None)? {
        let row = row?;
        let Some(id) = str_field(&row, "instance_id") else {
            continue;
        };
        if wanted.contains(&id) {
            rows.insert(id, row);
        }
    }
    let missing: Vec<&String> = ids.iter().filter(|id| !rows.contains_key(*id)).collect();
    if !missing.is_empty() {
        return Err(format!(
            "{} instance(s) missing from the parquet: {missing:?}",
            missing.len()
        )
        .into());
    }

    let mut instances = Vec::with_capacity(ids.len());
    for id in &ids {
        let row = &rows[id];
        let repo = req_str(row, "repo")?;
        let dataset_image = req_str(row, "image")?;
        let entry = lock
            .images
            .get(id)
            .ok_or_else(|| format!("{id}: no image in the lock"))?;
        // tasks.pinned_image's cross-check: the lock must describe the dataset's own image.
        let dataset_repository = dataset_image
            .rsplit_once(':')
            .map(|(repo, _)| repo)
            .unwrap_or(dataset_image.as_str());
        if dataset_repository != entry.repository {
            return Err(format!(
                "{id}: dataset image {dataset_repository:?} != lock {:?}",
                entry.repository
            )
            .into());
        }
        let image = format!("{}/{}@{}", lock.registry, entry.repository, entry.digest);

        let gold_patch = req_str(row, "patch")?;
        let test_patch = req_str(row, "test_patch")?;
        let fail_to_pass = list_field(row, "FAIL_TO_PASS")?;
        let pass_to_pass = list_field(row, "PASS_TO_PASS")?;
        if fail_to_pass.is_empty() {
            return Err(format!("{id}: FAIL_TO_PASS is empty").into());
        }
        let raw_eval = req_str(row, "eval_script")?;
        let eval_script = eval_script(&raw_eval);
        if !eval_script.contains(">>>>> End Test Output") {
            return Err(format!("{id}: generated eval script has no end marker").into());
        }

        instances.push(InstanceRow {
            instance_id: id.clone(),
            repo,
            version: req_str(row, "version")?,
            base_commit: req_str(row, "base_commit")?,
            image,
            problem_statement: req_str(row, "problem_statement")?,
            oracle_files: oracle_files(&gold_patch),
            gold_patch,
            test_patch,
            fail_to_pass,
            pass_to_pass,
            eval_script,
            parser: req_str(row, "log_parser")?,
        });
    }

    let mut seed = Seed {
        schema: SCHEMA,
        slug,
        dataset: DATASET,
        dataset_revision: DATASET_REVISION,
        swebench_version: SWEBENCH_VERSION,
        parser_version: PARSER_VERSION,
        image_lock_sha256,
        seed_sha256: String::new(),
        instances,
    };
    let unsigned = serde_json::to_string_pretty(&seed)?;
    seed.seed_sha256 = hex(&Sha256::digest(unsigned.as_bytes()));
    let signed = serde_json::to_string_pretty(&seed)?;
    fs::write(&out, format!("{signed}\n"))?;

    println!(
        "wrote {} — {} instances, seed_sha256 {}",
        out.display(),
        seed.instances.len(),
        seed.seed_sha256
    );
    Ok(())
}

/// The registry is not a dataset column; the lock carries it at the top level, but the seed
/// tool accepts it from the lock file instead of a hidden default.
fn str_field(row: &Row, name: &str) -> Option<String> {
    row.get_column_iter()
        .find(|(column, _)| column.as_str() == name)
        .and_then(|(_, field)| match field {
            Field::Str(value) => Some(value.clone()),
            Field::Bytes(bytes) => String::from_utf8(bytes.data().to_vec()).ok(),
            _ => None,
        })
}

fn req_str(row: &Row, name: &str) -> Result<String> {
    str_field(row, name).ok_or_else(|| format!("column {name} is missing or not a string").into())
}

fn list_field(row: &Row, name: &str) -> Result<Vec<String>> {
    let field = row
        .get_column_iter()
        .find(|(column, _)| column.as_str() == name)
        .map(|(_, field)| field)
        .ok_or_else(|| format!("column {name} is missing"))?;
    let values: Vec<String> = match field {
        Field::ListInternal(list) => list
            .elements()
            .iter()
            .map(|element| match element {
                Field::Str(value) => Ok(value.clone()),
                Field::Bytes(bytes) => Ok(String::from_utf8(bytes.data().to_vec())?),
                other => Err(format!("{name}: unexpected list element {other:?}").into()),
            })
            .collect::<Result<_>>()?,
        // A future dataset revision may ship the lists as JSON strings (tasks.py handles both).
        Field::Str(raw) => serde_json::from_str(raw)?,
        Field::Bytes(bytes) => serde_json::from_slice(bytes.data())?,
        other => return Err(format!("{name}: unexpected column type {other:?}").into()),
    };
    Ok(values)
}

fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        write!(out, "{byte:02x}").expect("writing to a String cannot fail");
    }
    out
}
